head.script:
scwin.onpageload = function() {
    var jsonData = [{
        col1: "test****"
    }, {
        col1: "a"
    }, {
        col1: "*a"
    }, {
        col1: "a*"
    }, {
        col1: "b"
    }, {
        col1: "b*"
    }]
    dataList1.setJSON(jsonData);
};
scwin.onpageunload = function() {};
scwin.unitTest = function() {
    //Unit test
    WebSquare.wUnit.start();
    //Test step 1. 샘플실행 후 "useFilter"버튼을 클릭한다.
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('gridView_column5_filter').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    //Test step 2. '사용자필터' 버튼을 클릭한다.
    WebSquare.wUnit.addCommand("set", "document.getElementsByClassName('w2list_listColumn w2list_listColumn_text w2grid_customFilter_list_listColumn_text')[0].click()");
    WebSquare.wUnit.addCommand("pause", "500");
    //Test step 3. selectbox를 클릭한다.
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('gridView_item_0_selectbox_column5_button').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    //Test step 4. '=' 를 클릭한다.
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('gridView_item_0_selectbox_column5_itemTable_1').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    //Test step 5. autocomplete을 클릭한다.
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('gridView_item_0_autocomplete_column5_button').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    //Test step 6. '*a' 를 클릭한다.
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('gridView_item_0_autocomplete_column5_itemTable_0').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    //Test step 7. '확인' 버튼을 클릭한다.
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('gridView_btnConform_column5').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    //Test step 8. 포커스를 옮기기 위해 "useFilter"버튼을 클릭한다.
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('gridView_column5_filter').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    //Test step 9. '*a'가 검색되어졌는지 확인한다.
    WebSquare.wUnit.addCommand("assert", "document.getElementsByClassName('w2grid_input')[0].innerText == '*a'", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    //Run and Stop test
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.unitTest();
